       c.NUMERIC_SCALE AS escala, c.IS_NULLABLE AS acepta_nulos,
       CASE WHEN c.COLUMN_NAME IN (N'*', N'HAUTO', N'HCAPP1', N'HCAPP2', N'HCAPP3', N'HCAPP4', N'HCAPP5', N'HCASE', N'HCCLI', N'HCOFI', N'HCRT10', N'HCRT11', N'HCRT12', N'HCRT2', N'HCRT3', N'HCRT4', N'HCRT5', N'HCRT6', N'HCRT7', N'HCRT8', N'HCRT9', N'HDASE', N'HDOFI', N'HDTDOC', N'HFAPP1', N'HFAPP2', N'HFAPP3', N'HFAPP4', N'HFAPP5', N'HFDES', N'HFECPRO', N'HGESTTAS', N'HHAPP1', N'HHAPP2', N'HHAPP3', N'HHAPP4', N'HHAPP5', N'HMDES', N'HMOD', N'HNAPP1', N'HNAPP2', N'HNAPP3', N'HNAPP4', N'HNAPP5', N'HNCLI', N'HNCUO', N'HNDOC', N'HOPER', N'HPBS', N'HPLZO', N'HPROD', N'HREGI', N'HSOLI', N'HSUBTIP', N'HTBAS', N'HTDES', N'HTERR', N'HTMER', N'HTMIN', N'HTOPE', N'HTSEG', N'HTSOL', N'HTTAR', N'HUAPP1', N'HUAPP2', N'HUAPP3', N'HUAPP4', N'HUAPP5', N'HUCAP', N'HUCAP_FIN', N'HUFAP', N'HUHAP', N'HUNAP', N'HUUAP', N'HVARI1', N'HVARI2', N'HVARI3', N'HVARI4', N'HVARI5', N'ID', N'ORD', N'RCODCOR', N'RCODGRU', N'RCODSEC', N'RCODTER', N'RCODUCO', N'RCODUNI', N'RDESCOR', N'RDESGRU', N'RDESSEC', N'RDESTER', N'RDESUCO', N'RDESUNI', N'RFEC') THEN 1 ELSE 0 END AS usada_por_reportes
FROM INFORMATION_SCHEMA.COLUMNS c
WHERE c.TABLE_SCHEMA = N'com_act' AND c.TABLE_NAME = N'WGATH002'
ORDER BY c.ORDINAL_POSITION;

-- 2. Tamaño (sin recorrer la tabla).
SELECT SUM(p.rows) AS filas
